$('ops-report-run').onclick=()=>{const a=$('ops-report-from').value,b=$('ops-report-to').value;if(!a||!b||a>b)return showToast('Choose a valid reporting period.');from=a;to=b;renderReports();};
const accessPanel=inject('access','<h3>Record visibility and staff settings</h3><p>Choose a staff member below to set which records they may access.</p><select id="ops-access-user"></select><div id="ops-scopes" class="ops-grid"></div><div class="ops-grid"><label>Department<input id="ops-department"></label><label>Annual leave entitlement<input id="ops-leave-days" type="number" min="0" max="366" step="0.5"></label></div><button id="ops-save-access" class="primary-button">Save record access</button><p id="ops-access-status" role="status"></p>');
const scopeModules=['requests','projects','tasks','crm','calendar','missions','assets','chat','finance','commercial','leave','training'];
async function loadAccess(){if(profile()?.role!=='admin')return;accounts=(await api().accessAccounts()).users;$('ops-access-user').innerHTML=options(accounts,u=>u.id,u=>u.full_name);await accessFields();}
async function accessFields(){const id=$('ops-access-user').value;if(!id)return;const rules=await api().opsData('record_access',{user_id:id});const setting=(await api().opsData('staff_work_settings',{user_id:id}))[0];const u=accounts.find(u=>u.id===id);$('ops-scopes').innerHTML=scopeModules.map(m=>`<label>${esc(m)}<select data-scope="${m}" ${u?.role==='admin'?'disabled':''}>${['own','projects','department','all'].map(v=>`<option value="${v}" ${v===(u?.role==='admin'?'all':rules.find(r=>r.module===m)?.scope||(u?.role==='manager'?'all':'projects'))?'selected':''}>${{own:'Own records',projects:'Assigned projects',department:'Department',all:'All records'}[v]}</option>`).join('')}</select></label>`).join('');$('ops-department').value=setting?.department||'';$('ops-leave-days').value=setting?.annual_leave_days??20;}
$('ops-access-user').onchange=()=>accessFields().catch(e=>showToast(e.message));$('ops-save-access').onclick=async()=>{try{const uid=$('ops-access-user').value;for(const x of document.querySelectorAll('[data-scope]'))await api().opsSave('record_access',{user_id:uid,module:x.dataset.scope,scope:x.value},'user_id,module');await api().opsSave('staff_work_settings',{user_id:uid,department:$('ops-department').value.trim(),annual_leave_days:Number($('ops-leave-days').value)},'user_id');$('ops-access-status').textContent='Saved. Record access applies on the next sync.';await refresh();}catch(e){$('ops-access-status').textContent=e.message;}};
function quoteApprovalOptions(){const allowed=currentUserCanSelfApprove(),f=$('quote-form'),selected=f.elements.status.value;f.elements.status.innerHTML=allowed?'<option value="Approved">Approved — your administrator approval</option><option value="Draft">Draft — finish later</option>':'<option value="Draft">Draft — requires another manager’s approval</option>';if(selected==='Draft'&&!allowed)f.elements.status.value='Draft';const note=$('quote-approval-note');if(note)note.textContent=allowed?'You may approve this quotation yourself. Save it, then use Send in Finance.':'Save a draft for another manager to approve, then use Send in Finance.';}
const sendNewQuote=$('quote-form').elements.sendNow;if(sendNewQuote){sendNewQuote.checked=false;sendNewQuote.disabled=true;sendNewQuote.closest('label')?.setAttribute('hidden','');}
