$('task-form').querySelector('.form-grid').insertAdjacentHTML('beforeend','<div class="field field-wide"><h3>Subtasks</h3><div id="ops-subtasks"></div><button type="button" id="ops-add-subtask">Add subtask</button></div><label class="field field-wide">Prerequisite tasks<select id="ops-dependencies" multiple size="4"></select><small>All prerequisites and subtasks must be complete before this task can be completed.</small></label><label class="field">Repeat after completion<select id="ops-recurrence"><option value="">Does not repeat</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label>');
function subtask(t={id:crypto.randomUUID(),title:'',done:false}){const r=document.createElement('label');r.className='ops-subtask';r.dataset.subtask=t.id;r.innerHTML=`<input type="checkbox" ${t.done?'checked':''} aria-label="Completed"><input type="text" value="${esc(t.title)}" aria-label="Subtask title"><button type="button" aria-label="Remove subtask">×</button>`;r.querySelector('button').onclick=()=>r.remove();$('ops-subtasks').append(r);}
$('ops-add-subtask').onclick=()=>subtask();
const openTaskOriginal=openTaskDialog;openTaskDialog=function(...args){openTaskOriginal(...args);const t=state.tasks.find(x=>x.id===editingTaskId);$('ops-subtasks').innerHTML='';(t?.subtasks||[]).forEach(subtask);$('ops-dependencies').innerHTML=state.tasks.filter(x=>x.id!==t?.id).map(x=>`<option value="${esc(x.id)}" ${(t?.dependencies||[]).includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('');$('ops-recurrence').value=t?.recurrence||'';let fileButton=$('ops-task-evidence-link');if(!fileButton){fileButton=document.createElement('button');fileButton.type='button';fileButton.id='ops-task-evidence-link';$('task-form').querySelector('.dialog-actions').prepend(fileButton);}fileButton.hidden=!t?.evidencePath;fileButton.textContent='Open attached evidence';fileButton.onclick=()=>api().openFile(t.evidencePath).catch(e=>showToast(e.message));};
function taskFields(){return {subtasks:[...document.querySelectorAll('[data-subtask]')].map(r=>({id:r.dataset.subtask,title:r.querySelector('[type=text]').value.trim(),done:r.querySelector('[type=checkbox]').checked})).filter(x=>x.title),dependencies:[...$('ops-dependencies').selectedOptions].map(x=>x.value),recurrence:$('ops-recurrence').value};}
const templates={mapping:['Confirm scope and client acceptance','Plan capture and equipment','Confirm operational approvals','Capture imagery and checkpoints','Process and quality-check data','Deliver maps and obtain acceptance'],inspection:['Confirm inspection scope','Prepare asset list and flight plan','Confirm operational approvals','Capture inspection evidence','Review findings and defects','Deliver report and obtain acceptance'],rpl:['Confirm training scope and enrolment','Check learner documents','Plan instructors and equipment','Deliver theory and practical sessions','Assess competence and retain evidence','Complete certification handover'],hire:['Confirm hire dates and acceptance','Reserve equipment kit','Record checkout condition','Track return and condition','Resolve damage or missing items','Close hire and billing'],grant:['Confirm eligibility and partner roles','Gather supporting documents','Prepare narrative and budget','Internal review and approval','Submit before deadline','Record outcome and reporting obligations']};
$('project-form').querySelector('.form-grid').insertAdjacentHTML('beforeend','<label class="field field-wide">Workflow template<select name="workflowTemplate"><option value="">Start without a template</option><option value="mapping">Mapping and geospatial delivery</option><option value="inspection">Inspection</option><option value="rpl">RPL training</option><option value="hire">Equipment hire</option><option value="grant">Grant application and delivery</option></select></label>');
function applyTemplate(p,key){if(!templates[key])return;const steps=templates[key],start=day(),span=Math.max(0,Math.round((new Date(p.deadline)-new Date(start))/86400000));let prior;steps.forEach((title,i)=>{const id='t-'+crypto.randomUUID();state.tasks.push({id,title,project:p.id,owner:p.owner,due:addDays(start,Math.min(span,Math.ceil(span*(i+1)/steps.length))),status:'To Do',priority:i===steps.length-1?'High':'Medium',output:title+' — retain completion evidence',evidence:'',updated:day(),dependencies:prior?[prior]:[],list:state.boardLists.find(l=>l.status==='To Do')?.id});prior=id;});p.workflowTemplate=key;p.milestones=[{id:crypto.randomUUID(),title:'Scope and approvals confirmed',due:start,complete:false,cost:0},{id:crypto.randomUUID(),title:'Client-ready delivery',due:p.deadline,complete:false,cost:0}];}
