function showPriorities(){const current=priorities.find(p=>p.day===day())?.task_ids||[];$('ops-priorities').innerHTML=current.map(id=>state.tasks.find(t=>t.id===id)).filter(Boolean).map(t=>`<button class="ops-priority" data-ops-task="${esc(t.id)}">${esc(t.title)} · ${esc(t.status)}</button>`).join('')||'<p>Choose up to three realistic priorities for today.</p>';}
$('ops-choose-priorities').onclick=()=>{const ids=priorities.find(p=>p.day===day())?.task_ids||[];const d=modal('ops-focus','Choose today’s priorities',form('ops-focus-form',state.tasks.filter(t=>t.owner===me()&&t.status!=='Done').map(t=>`<label><input type="checkbox" name="task" value="${esc(t.id)}" ${ids.includes(t.id)?'checked':''}> ${esc(t.title)}</label>`).join('')));bind('ops-focus-form',async(v,f)=>{const ids=new FormData(f).getAll('task');if(ids.length>3)throw new Error('Choose at most three priorities.');await api().opsSave('daily_priorities',{day:day(),task_ids:ids},'user_id,day');d.close();await refresh();});};
